"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["92451"],{27916(e){e.exports=JSON.parse('{"id":"FIN-306","slug":"complementary-good","term":"Complementary Good","also_known_as":[],"difficulty":"Beginner","definition":"A complementary good is a product that is typically used together with another, so that demand for one depends on demand for the other, such as printers and ink or cars and petrol.","explanation":["When two goods are complements, a rise in the price of one tends to reduce demand for the other. If cars become more expensive, fewer people buy them, which also reduces demand for petrol, tyres and car insurance. This gives complementary goods a negative cross-price elasticity.","Other examples include smartphones and apps, coffee machines and coffee pods, tennis rackets and tennis balls, and flights and hotel rooms.","Businesses often use complements in their pricing strategies. A company may sell a games console at a low price, even at a loss, to build a large base of customers who will then buy profitable games. Printer manufacturers have often sold printers cheaply and earned more from ink cartridges.","Understanding complements also helps businesses predict demand. A rise in new home sales, for example, is likely to increase demand for furniture, appliances and home improvement products."],"note":"","total":1500,"prev":{"slug":"competitive-advantage","term":"Competitive Advantage"},"next":{"slug":"completion-accounts","term":"Completion Accounts"}}')}}]);